package com.tuap.backend.auth;
import java.util.Locale; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
@Service public class GoogleOnboardingService {
 private final PendingSocialAuthService pending; private final ClienteDAO clientes; private final EntrenadorDAO entrenadores; private final AuthIdentityService identities; private final ConsentService consents;
 public GoogleOnboardingService(PendingSocialAuthService p,ClienteDAO c,EntrenadorDAO e,AuthIdentityService i,ConsentService s){pending=p;clientes=c;entrenadores=e;identities=i;consents=s;}
 @Transactional public AuthenticatedUser complete(GoogleOnboardingRequest request){if(request==null||request.role()==null||blank(request.nombre())||blank(request.apellido())||!request.acceptTerms()||!request.acceptPrivacy())throw new IllegalArgumentException("Solicitud de registro con Google inválida"); PendingSocialAuth state=pending.consume(request.pendingToken());String email=state.getVerifiedEmail().trim().toLowerCase(Locale.ROOT);if(clientes.findByEmail(email).isPresent()||entrenadores.findByEmail(email).isPresent())throw new AuthIdentityConflictException();AuthenticatedUser user;if(request.role()==Role.CLIENTE){Cliente c=new Cliente(request.nombre().trim(),request.apellido().trim(),email,null,"ROLE_CLIENTE",0,0,0,"","","");c=clientes.save(c);user=new AuthenticatedUser(c.getId(),email,Role.CLIENTE);}else if(request.role()==Role.ENTRENADOR){Entrenador e=new Entrenador(request.nombre().trim(),request.apellido().trim(),email,null,"ROLE_ENTRENADOR","",0,"",0,"","","","");e=entrenadores.save(e);user=new AuthenticatedUser(e.getId(),email,Role.ENTRENADOR);}else throw new IllegalArgumentException("Rol inválido");identities.linkIdentity(user,AuthProvider.GOOGLE,state.getProviderSubject(),email);consents.recordRegistration(user,true,true,request.marketingConsent());return user;}
 private boolean blank(String s){return s==null||s.isBlank();}
}
